// Cadence : semaine, 8h15-19h (Paris). Toutes les minutes si un véhicule roule, sinon toutes les 5 minutes.
const now = DateTime.now().setZone('Europe/Paris');
const m = now.hour * 60 + now.minute;
if (now.weekday > 5 || m < 8 * 60 + 15 || m > 19 * 60) return [];
const s = $getWorkflowStaticData('global');
if (s.bloque && Date.now() < s.bloque) return []; // pause 30 min après un refus de connexion
const ecoule = (Date.now() - (s.dernier || 0)) / 60000;
if (!s.enRoute && ecoule < 4.5) return [];
return [{ json: { lancement: now.toISO() } }];

// Lit Quartix (QWS v2) en LECTURE SEULE. L'authentification est faite par le nœud « Auth Quartix »
// avec l'identifiant n8n chiffré : aucun mot de passe ne passe dans les données.
const r = $input.first().json || {};
const now = DateTime.now().setZone('Europe/Paris');
const jour = now.toFormat('yyyy-MM-dd');
const s = $getWorkflowStaticData('global');
const b = r.body || {};
const d = b.Data || b.data || {};
const tok = d.AccessToken || d.accessToken;
if (!tok) {
  s.bloque = Date.now() + 30 * 60000; s.dernier = Date.now(); s.enRoute = false;
  const m = (b.Meta && b.Meta.Message) || (b.meta && b.meta.message) || (r.error && r.error.message) || '';
  return [{ json: { cle: 'etat', etat_json: JSON.stringify({ jour, maj: now.toISO(), erreur: 'Connexion Quartix refusée', code: r.statusCode || null, message: String(m).slice(0, 200) }), maj: now.toISO() } }];
}
s.bloque = 0;
const base = 'https://qws.quartix.net/v2/api';
const H = { AccessToken: tok };
const get = async (p) => { const x = await this.helpers.httpRequest({ method: 'GET', url: base + p, headers: H, json: true, timeout: 15000 }); return (x && (x.Data || x.data)) || []; };
const [vehicules, live, trajets, gestion] = [await get('/vehicles'), await get('/vehicles/live'), await get('/vehicles/trips?StartDay=' + jour + '&EndDay=' + jour), await get('/vehicles/management')];
function calculer(vehicules, live, trajets, gestion, maintenantISO) {
  const SUIVI_ARRETS = ['FL 192 RP']; // Vivaro Blanc (techniciens). Le Vivaro Bleu = véhicule de Laurent, pas de suivi des durées.
  const lieu = s => String(s || '').replace(/, France$/, '').trim();
  const estDepot = s => /^climatpro$/i.test(String(s || '').trim()) || /Chem(in|\.) de Dandon/i.test(String(s || ''));
  const out = [];
  for (const v of vehicules) {
    const L = live.find(x => x.VehicleId === v.VehicleId) || {};
    const G = gestion.find(x => x.VehicleID === v.VehicleId) || {};
    const enRoute = (L.Speed || 0) > 0 || (L.LastEventDescription && L.LastEventDescription !== 'Ignition-Off');
    const adr = lieu(String(L.LocationText || '').replace(/^.*? à /, '').replace(/ depuis .*$/, ''));
    const T = trajets.filter(t => t.VehicleID === v.VehicleId)
      .sort((a, b) => String(a.StartDateTime).localeCompare(String(b.StartDateTime)))
      .filter(t => (t.Distance || 0) >= 0.15); // micro-déplacements (< 150 m) ignorés : ils ne coupent pas un arrêt
    const arrets = [];
    if (SUIVI_ARRETS.includes(v.RegistrationNumber)) {
      for (let i = 0; i < T.length; i++) {
        const arr = T[i], dep = T[i + 1];
        const fin = dep ? dep.StartDateTime : (enRoute ? null : maintenantISO);
        if (!fin) continue;
        const min = Math.round((Date.parse(fin) - Date.parse(arr.EndDateTime)) / 60000);
        if (min < 5 || estDepot(arr.EndLocation)) continue;
        arrets.push({ lieu: lieu(arr.EndLocation), lat: arr.EndLat, lon: arr.EndLong, arrivee: arr.EndDateTime, depart: dep ? dep.StartDateTime : null, minutes: min, enCours: !dep });
      }
    }
    out.push({
      id: v.VehicleId, immat: v.RegistrationNumber, nom: v.Description,
      enRoute, vitesse: L.Speed || 0, adresse: adr, depot: estDepot(adr), lat: L.Latitude, lon: L.Longitude,
      dernierSignal: L.LastEventDateTime || null, evenement: L.LastEventDescription || '',
      km: Math.round(T.reduce((s, t) => s + (t.Distance || 0), 0) * 10) / 10,
      echeances: { revision: G.ServiceDueDate || null, assurance: G.InsuranceDueDate || null, ct: G.TestDueDate || null },
      arrets
    });
  }
  return out;
}

const etat = calculer(vehicules, live, trajets, gestion, now.toISO());
s.dernier = Date.now();
s.enRoute = etat.some(v => v.enRoute);
return [{ json: { cle: 'etat', etat_json: JSON.stringify({ jour, maj: now.toISO(), vehicules: etat }), maj: now.toISO() } }];
